import{NPC_ART}from'./selected-npc-art.mjs';
const sha=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(v=>v.toString(16).padStart(2,'0')).join('');
// Original PNG bytes only. Loader owns decoded bitmaps until explicit dispose.
export async function loadSelectedS4NPCs({readBytes,decode,signal}={}){if(typeof readBytes!=='function'||typeof decode!=='function')throw Error('NPC_PINNED_LOADER_REQUIRED');const images=[],alive=()=>{if(signal?.aborted)throw Error('NPC_LOAD_ABORTED')};try{for(const row of NPC_ART){alive();const raw=await readBytes(row),bytes=raw instanceof ArrayBuffer?new Uint8Array(raw.slice(0)):new Uint8Array(raw);if(bytes.byteLength!==row.bytes||await sha(bytes)!==row.sha256)throw Error('NPC_ORIGINAL_PIN_MISMATCH');alive();const image=await decode(bytes);images.push(image);alive();if(image.width!==row.width||image.height!==row.height)throw Error('NPC_ORIGINAL_DIMENSIONS_MISMATCH')}let disposed=false;return Object.freeze({sprites(){if(disposed)throw Error('NPC_ASSETS_DISPOSED');return NPC_ART.map((r,i)=>({row:r,image:images[i]}))},dispose(){if(disposed)return;disposed=true;for(const im of images)im.close?.()}})}catch(e){for(const im of images)im.close?.();throw e}}
// Call inside existing background→actors→foreground→shared ambient compositor, never after ambient.
// Player participates in the same foot-y ordering. Renderer owns player draw and selected foreground clips.
export function drawS4NPCAndPlayerLayer({ctx,camera,mapId,npcs,playerFoot,drawPlayer}){if(typeof drawPlayer!=='function'||!Array.isArray(camera))throw Error('ACTOR_COMPOSITOR_REQUIRED');const entries=[{y:playerFoot[1],id:'player',draw:drawPlayer}];if(mapId==='world:area:S4_GOHYEON_GREENBELT')for(const {row:r,image}of npcs.sprites()){const [sx,sy,ex,ey]=r.sourceBounds,scale=80/(ey-sy),w=(ex-sx)*scale;entries.push({y:r.foot[1],id:r.pointId,draw:()=>ctx.drawImage(image,sx,sy,ex-sx,ey-sy,r.foot[0]-camera[0]-w/2,r.foot[1]-camera[1]-80,w,80)})}entries.sort((a,b)=>a.y-b.y||a.id.localeCompare(b.id));for(const e of entries)e.draw();return{order:entries.map(e=>e.id),newArt:false,ambientApplications:0,visibleHeight:80}}
